class Solution {
    public int[] shuffle(int[] nums, int n) {
        int[] res = new int[2 * n];
        for (int i = 0; i < n; i++) {
            res[2 * i] = nums[i];
            res[2 * i + 1] = nums[i + n];
        }
        return res;
    }
}

class Solution {
    public int[] shuffle(int[] nums, int n) {
        for (int i = 0; i < n; i++) {
            nums[i] = nums[i] | (nums[i + n] << 10);
        }
        int idx = 2 * n - 1;
        for (int i = n - 1; i >= 0; i--) {
            int y = nums[i] >> 10;
            int x = nums[i] & 1023;
            nums[idx--] = y;
            nums[idx--] = x;
        }
        return nums;
    }
}
